using System;
using System.IO;
using System.Security.Cryptography;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace RoomLab.Native
{
    public static class NativeCodecChecks
    {
        public static int Run(string directory){int checks=0;void Check(bool ok,string text){checks++;if(!ok)throw new Exception("Native codec Unity: "+text);}var expected=JObject.Parse(File.ReadAllText(Path.Combine(directory,"expected.json")));foreach(JObject fixture in (JArray)expected["fixtures"]){string file=(string)fixture["file"];var p=new NativeProject();p.Assets.Add(new NativeAsset{Id="test",Path="assets/"+file,Bytes=File.ReadAllBytes(Path.Combine(directory,"fixtures",file))});using(var assets=NativeDemoAssets.Decode(p)){var frames=assets.Frames["test"];Check(frames.Length==((JArray)fixture["frame_sha256"]).Count,"frame count "+file);for(int f=0;f<frames.Length;f++){var texture=frames[f].texture;var pixels=texture.GetPixels32();byte[] rgba=new byte[pixels.Length*4];for(int y=0;y<texture.height;y++)for(int x=0;x<texture.width;x++){var c=pixels[(texture.height-1-y)*texture.width+x];int at=(y*texture.width+x)*4;rgba[at]=c.r;rgba[at+1]=c.g;rgba[at+2]=c.b;rgba[at+3]=c.a;}using(var sha=SHA256.Create()){string hash=BitConverter.ToString(sha.ComputeHash(rgba)).Replace("-","").ToLowerInvariant();Check(hash==(string)fixture["frame_sha256"][f],"RGBA/row order/transparent/composition "+file+" "+f);}Check(ShaderPixels(frames[f]),"actual sprite shader/row/alpha "+file+" "+f);}
                    if(frames.Length>1){var timing=assets.Timings["test"];Check(timing.Plays==(uint)fixture["play_count"],"loop count");double elapsed=0;for(int i=0;i<frames.Length;i++){Check(timing.Milliseconds[i]==(uint)fixture["durations_ms"][i],"unequal frame duration");if(timing.Milliseconds[i]>0)Check(assets.Get("test",(elapsed+.001)/1000)==frames[i],"time-based container frame");elapsed+=timing.Milliseconds[i];}Check(assets.Get("test",(elapsed*(timing.Plays==0?3:timing.Plays)+1)/1000)==(timing.Plays==0?frames[0]:frames[frames.Length-1]),"finite/infinite termination");}}
            }
            foreach(string ext in new[]{"gif","webp"}){var p=new NativeProject();p.Assets.Add(new NativeAsset{Id="bad",Path="assets/bad."+ext,Bytes=new byte[]{1,2,3}});bool rejected=false;try{using(var bad=NativeDemoAssets.Decode(p)){} }catch(NativeDataException){rejected=true;}Check(rejected,"bad "+ext+" rejected");}Debug.Log("NATIVE_UNITY_CODEC_PASS checks="+checks+" runtime="+(Application.isEditor?"Editor":"WindowsMonoPlayer")+" nativeDLL=true shaderFrames=true");return checks;}
        static bool ShaderPixels(Sprite sprite){var go=new GameObject("Codec shader isolated");go.layer=6;var renderer=go.AddComponent<SpriteRenderer>();renderer.sprite=sprite;var cameraObject=new GameObject("Codec shader camera");var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;camera.cullingMask=1<<6;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.clear;camera.orthographic=true;camera.orthographicSize=sprite.texture.height/64f;camera.aspect=(float)sprite.texture.width/sprite.texture.height;camera.transform.position=new Vector3(0,0,-10);var rt=RenderTexture.GetTemporary(sprite.texture.width,sprite.texture.height,0,RenderTextureFormat.ARGB32);var before=RenderTexture.active;Texture2D image=null;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();var wanted=sprite.texture.GetPixels32();var actual=image.GetPixels32();for(int i=0;i<wanted.Length;i++){if(Math.Abs(actual[i].a-wanted[i].a)>2)return false;if(wanted[i].a==255&&(Math.Abs(actual[i].r-wanted[i].r)>2||Math.Abs(actual[i].g-wanted[i].g)>2||Math.Abs(actual[i].b-wanted[i].b)>2))return false;}return true;}finally{camera.targetTexture=null;RenderTexture.active=before;RenderTexture.ReleaseTemporary(rt);NativeDemoAssets.Release(image);NativeDemoAssets.Release(cameraObject);NativeDemoAssets.Release(go);}}
    }
}
